update public.learning_paths
set
  title = 'Applied Anthropology',
  goal = 'Applied Anthropology',
  summary = 'This advanced undergraduate anthropology elective focuses on the application of anthropological core concepts to professional ethics, participatory design, mixed methods, organizational practice, environmental and humanitarian applications, policy translation, and a capstone client brief.',
  data = $apanjson${"slug": "applied-anthropology", "title": "Applied Anthropology", "description": "This advanced undergraduate anthropology elective focuses on the application of anthropological core concepts to professional ethics, participatory design, mixed methods, organizational practice, environmental and humanitarian applications, policy translation, and a capstone client brief.", "topics": [{"id": "5c6a4326-a802-4b1a-88a5-a86ca9805109", "type": "topic", "title": "Applied Anthropology as Public Practice", "description": "This opening section frames anthropology as a discipline that studies human life while also working with communities, organizations, and public institutions to solve practical problems.", "children": [{"id": "b027820f-d3a0-4d2b-b86a-32ba7e3216b9", "type": "subtopic", "title": "Anthropology beyond the academy", "children": [{"id": "9ef7b699-39ec-4423-a724-e38c529f678c", "type": "concept", "title": "Applied, practicing, public, and engaged anthropology"}, {"id": "257b2bba-0a14-4d11-aea5-f0f0398883d1", "type": "concept", "title": "Four-field contributions to real-world problems"}, {"id": "e867479f-c832-483c-84c7-d7260eda12c4", "type": "concept", "title": "Professional roles, deliverables, and career pathways"}], "description": "Students learn how anthropological knowledge moves into health, education, design, development, heritage, environmental work, and policy."}, {"id": "2f3d3b53-690f-478a-94bb-a088a4e9ee7c", "type": "subtopic", "title": "The applied problem frame", "children": [{"id": "47a767d4-a39b-41d9-be0f-9a86a9f3a56c", "type": "concept", "title": "Problem definition and scope"}, {"id": "2244120e-8ba8-4ba8-bf7b-8b9939c60789", "type": "concept", "title": "Cultural assumptions behind policy or service failure"}, {"id": "bcdf7a58-a8f4-4dcc-9f9a-fdf2977e409f", "type": "concept", "title": "From research question to client or community brief"}], "description": "The point is to translate broad social questions into actionable, culturally informed problem statements."}, {"id": "4b508994-e2f9-492e-923a-5d4764df226b", "type": "subtopic", "title": "Practice domains", "children": [{"id": "9cfa90f8-0f82-43c2-8e57-789a22fa484f", "type": "concept", "title": "Health and public health"}, {"id": "6f185e2c-1331-4bf2-8aee-68d24f48e6ef", "type": "concept", "title": "Business, design, and organizations"}, {"id": "fcf5ffd0-3df8-40a8-93f4-eb60f08cc01e", "type": "concept", "title": "Development, heritage, environment, and law"}], "description": "Students survey the major arenas where anthropologists intervene and advise."}]}, {"id": "55a14ff2-7943-41ad-b3ed-be2c11ac3a0a", "type": "topic", "title": "Public, Engaged, and Collaborative Anthropology", "description": "Applied work depends on relationships. This section teaches students to treat communities as partners in knowledge production rather than as passive subjects.", "children": [{"id": "96d0e26c-607d-45e6-b3d2-042f94063bdc", "type": "subtopic", "title": "Public anthropology", "children": [{"id": "5d9ef6e8-df4e-4404-beeb-472bc64ab1ab", "type": "concept", "title": "Public scholarship and accessible writing"}, {"id": "38410b2c-ed59-402c-a9b7-0eefd5fe7b09", "type": "concept", "title": "Media, museums, podcasts, and community forums"}, {"id": "6d29a975-7771-4ae9-8733-9cb533064315", "type": "concept", "title": "Risks of oversimplification and representation"}], "description": "Students learn how anthropologists contribute to civic debates, public understanding, and institutional decision-making."}, {"id": "a627c27b-d04c-4faf-b018-c81716344100", "type": "subtopic", "title": "Engaged and collaborative research", "children": [{"id": "9e9ea889-1ad7-4046-95e1-3cb56a89fb80", "type": "concept", "title": "Co-design and shared agenda setting"}, {"id": "2fe650bf-a315-4cae-b3ee-4f71c45f0b82", "type": "concept", "title": "Community review of findings"}, {"id": "3bc6410b-9a83-4863-a8d6-338df68cddf7", "type": "concept", "title": "Power, reciprocity, and accountability"}], "description": "The gist is that research design, interpretation, and action can be shared with affected communities."}, {"id": "e8bb34c7-d3e2-4085-9562-31a9ae8f1dae", "type": "subtopic", "title": "Participatory action approaches", "children": [{"id": "fba8442f-f4c8-4c46-b84c-e2325361186f", "type": "concept", "title": "Participatory action research"}, {"id": "2837ac2b-e0c2-4afc-ba24-2a4d26a0a094", "type": "concept", "title": "Community-based participatory research"}, {"id": "83968225-11cc-48e5-a976-f06ffa03f12b", "type": "concept", "title": "Empowerment and capacity-building models"}], "description": "Students examine approaches where inquiry and social change proceed together."}]}, {"id": "3b5c62a5-d629-4031-a388-93187efc3e60", "type": "topic", "title": "Ethics of Intervention and Professional Accountability", "description": "Applied anthropology raises ethical questions because findings can shape resources, risks, reputations, and policies. This section builds a practical ethics toolkit.", "children": [{"id": "b33c7fc6-efb9-4012-82f1-4c3a10bd30f0", "type": "subtopic", "title": "Consent, confidentiality, and risk", "children": [{"id": "3ea86b83-8c67-4ed6-ae35-2aae2763ff8e", "type": "concept", "title": "Informed consent in organizational and community contexts"}, {"id": "9a169827-adec-4796-afee-fe4740ee9657", "type": "concept", "title": "Anonymity, confidentiality, and deductive disclosure"}, {"id": "dee4e6f8-7fb5-4fef-b91e-57992a56b9df", "type": "concept", "title": "Risk assessment for vulnerable groups"}], "description": "Students learn why ethical practice goes beyond forms and requires judgment in messy field settings."}, {"id": "034c84c2-0734-4174-a433-489106b0f34b", "type": "subtopic", "title": "Power and intervention", "children": [{"id": "f71736b5-1a10-4e4f-b77a-e53b07f2a50c", "type": "concept", "title": "Colonial legacies and extractive research"}, {"id": "81ec8bab-34ce-4b79-bd9e-bb1a97b0ca5f", "type": "concept", "title": "Do-no-harm and beneficence"}, {"id": "56169bf0-ea7a-46ca-8c47-293c61914edd", "type": "concept", "title": "Refusal, dissent, and community control"}], "description": "The focus is on how anthropologists avoid reproducing inequality while trying to help."}, {"id": "9cc2c6c0-080a-439b-bb96-65a031a5d763", "type": "subtopic", "title": "Professional standards", "children": [{"id": "36043a87-07af-44b1-b3ad-aa2e8bd3b260", "type": "concept", "title": "AAA and SfAA ethical guidance"}, {"id": "c699e70c-f590-4838-974f-b0d509a760b3", "type": "concept", "title": "IRB and non-IRB practice settings"}, {"id": "a40d0a6b-309c-4737-8eb4-fea6be9b93d9", "type": "concept", "title": "Conflicts of interest and client pressure"}], "description": "Students connect classroom ethics to real professional codes and institutional review processes."}]}, {"id": "202ce613-c0b1-48a4-9705-5e680830c52d", "type": "topic", "title": "Ethnographic Methods for Applied Problem Solving", "description": "This section turns ethnography into an applied toolkit for understanding behavior, meaning, institutions, and everyday constraints.", "children": [{"id": "2d3540e2-d878-4bad-b9fe-adf1b205d82f", "type": "subtopic", "title": "Observation and fieldnotes", "children": [{"id": "43e9df2f-7bdd-45db-95d0-c127fd503266", "type": "concept", "title": "Participant observation"}, {"id": "3c8b34d7-d639-438d-bda2-dd2263b47851", "type": "concept", "title": "Jottings, fieldnotes, and analytic memos"}, {"id": "1e1d28df-fc07-46eb-b431-3473e598174c", "type": "concept", "title": "Reflexivity and positionality"}], "description": "Students practice seeing routine life as data without reducing people to isolated variables."}, {"id": "77307fd4-f3d9-4c9f-b1b4-510f84fa031a", "type": "subtopic", "title": "Interviewing and focus groups", "children": [{"id": "a1cc3b83-ef81-4262-bcb7-f2bcb34031b5", "type": "concept", "title": "Semi-structured interviews"}, {"id": "132bfe73-7e04-44f2-ac02-2fbd09bbb9ac", "type": "concept", "title": "Key informant interviews"}, {"id": "a28046ff-3df8-44fd-9bf4-2735e83f70cf", "type": "concept", "title": "Focus-group facilitation and limits"}], "description": "The point is to elicit experience, meanings, narratives, and decision processes."}, {"id": "23886354-b40f-4140-b2bc-8698a2ecf5f2", "type": "subtopic", "title": "Rapid and team-based ethnography", "children": [{"id": "086bbb27-6159-4782-8da1-4e6443af46e0", "type": "concept", "title": "Rapid assessment procedures"}, {"id": "041b2adc-2e7d-4fdc-afa4-6eafa12244e7", "type": "concept", "title": "Team coding and calibration"}, {"id": "1238327e-aa71-49ac-807f-86125d59c600", "type": "concept", "title": "Validity under time constraints"}], "description": "Students learn faster research formats used in organizations, health settings, policy, and design."}]}, {"id": "bec0ae3d-2ff6-4e06-a3fa-8fc0477a4627", "type": "topic", "title": "Needs Assessment, Stakeholder Analysis, and Asset Mapping", "description": "Applied projects usually begin by learning what people need, what they already have, and which institutions shape the problem.", "children": [{"id": "90a2f2e9-4823-4642-aeee-fafaddb84933", "type": "subtopic", "title": "Needs and asset assessment", "children": [{"id": "d9cc5be2-ff74-4c4e-9f75-7eae11175ad9", "type": "concept", "title": "Needs assessment questions"}, {"id": "d21ca2bd-91d1-42d1-9779-9ad6dc7ef275", "type": "concept", "title": "Asset-based community development"}, {"id": "1282a69f-44e3-4a60-930e-b95692498716", "type": "concept", "title": "Service gaps and informal support systems"}], "description": "Students learn to map deficits without ignoring community strengths."}, {"id": "660ce73a-976d-4b63-9a78-67da326b360b", "type": "subtopic", "title": "Stakeholder analysis", "children": [{"id": "93bc00b7-40cb-4615-ba10-5458e0d4c565", "type": "concept", "title": "Stakeholder identification"}, {"id": "68f37a5a-fb54-4801-a264-a3d77e519878", "type": "concept", "title": "Power-interest mapping"}, {"id": "edecdf90-a677-42b2-ae31-f3ec007d5676", "type": "concept", "title": "Coalitions, gatekeepers, and brokers"}], "description": "The goal is to identify who is affected, who has power, who has knowledge, and who can block or sustain change."}, {"id": "4af5a061-d1e4-4d72-bdb8-e87c0dee502c", "type": "subtopic", "title": "Context and feasibility", "children": [{"id": "808d8159-2072-43fd-a048-22fe20c3378e", "type": "concept", "title": "Organizational capacity"}, {"id": "26a12fca-8907-4488-bd70-4af255d088d9", "type": "concept", "title": "Political and funding constraints"}, {"id": "51e319e4-3d41-4708-83e4-8ba9a56aa4c0", "type": "concept", "title": "Cultural fit and implementation readiness"}], "description": "Students learn to connect cultural insight to institutional constraints."}]}, {"id": "e6248b33-08bd-4011-9792-f7e1691bca92", "type": "topic", "title": "Program Evaluation and Impact Learning", "description": "Evaluation helps applied anthropologists assess whether programs are working, for whom, why, and under what conditions.", "children": [{"id": "5c8f5037-34bc-41c0-bd70-beea15dd62b8", "type": "subtopic", "title": "Logic models and theories of change", "children": [{"id": "83b7706d-b2d4-4312-a780-0afe8bc8c55a", "type": "concept", "title": "Inputs, activities, outputs, outcomes, and impacts"}, {"id": "aeff7524-2842-4916-b987-355df85f83d1", "type": "concept", "title": "Causal pathways and cultural assumptions"}, {"id": "40bb11a7-4b21-4cb4-bc0e-3453db73e8db", "type": "concept", "title": "Evaluation questions aligned to stakeholder use"}], "description": "Students learn to make assumptions visible before evaluating an intervention."}, {"id": "c0027dac-17e7-44ff-84b4-cc0ee2997c0c", "type": "subtopic", "title": "Process and implementation evaluation", "children": [{"id": "a88dcece-1a82-400e-bd9e-8b91222ffc26", "type": "concept", "title": "Fidelity and adaptation"}, {"id": "163eb180-dab8-428a-88c9-9869d8893e2a", "type": "concept", "title": "Frontline discretion"}, {"id": "244ed382-8af6-4595-993d-861fa03e8d05", "type": "concept", "title": "Participant experience and barriers"}], "description": "The gist is that how a program is delivered often explains whether it succeeds."}, {"id": "4016db72-9233-4e6b-ae41-6b82c8a9088d", "type": "subtopic", "title": "Outcome, impact, and utilization", "children": [{"id": "bcc632a7-1cad-4844-906a-e6ad5cc93601", "type": "concept", "title": "Outcome indicators"}, {"id": "10ab0463-a83c-4add-aa8a-cf24ab38e655", "type": "concept", "title": "Mixed-method evidence"}, {"id": "9a81edc0-7f35-4186-85c1-de4b6a763dfe", "type": "concept", "title": "Reporting findings for action"}], "description": "Students learn to communicate evaluative evidence so it can improve decisions."}]}, {"id": "b6c79191-ca24-499f-bf7b-e54dc33960f8", "type": "topic", "title": "Design Anthropology and User Research", "description": "Design anthropology applies ethnographic insight to products, services, spaces, systems, and user experiences.", "children": [{"id": "fd5a5a4b-d6ff-4d38-af7d-bcd6c12156f4", "type": "subtopic", "title": "Human-centered and ethnographic design", "children": [{"id": "b5e44bca-2e27-4284-a4ef-78bb5b5715f0", "type": "concept", "title": "Contextual inquiry"}, {"id": "89b68ae3-3dc9-4850-8e54-6f308f28f4b4", "type": "concept", "title": "Journey mapping"}, {"id": "68289a31-6616-49ae-af83-b60346e55b39", "type": "concept", "title": "Pain points, workarounds, and tacit practice"}], "description": "Students learn how anthropology can reveal needs that surveys or usage metrics miss."}, {"id": "3a1b5dac-60a4-4f50-92f3-695faa5e8edb", "type": "subtopic", "title": "Co-design and prototyping", "children": [{"id": "a36ebfb2-5d3f-4504-82f6-05cf6cc0b953", "type": "concept", "title": "Participatory workshops"}, {"id": "1356c19b-060f-40c9-bd91-fec6e7dc3267", "type": "concept", "title": "Personas and scenarios used carefully"}, {"id": "28eed580-c4b6-4cda-95cf-4ab618fcfe79", "type": "concept", "title": "Low-fidelity prototyping and feedback loops"}], "description": "The point is to turn field insight into testable service or product concepts."}, {"id": "8d1ed789-4535-4824-8558-2e2cc474405a", "type": "subtopic", "title": "Organizations and innovation", "children": [{"id": "1fccf953-4276-49a4-9a7c-b25bcadeaa68", "type": "concept", "title": "Organizational routines"}, {"id": "b5e5c96a-01b1-4514-8f6e-7510d6cb3bef", "type": "concept", "title": "Change management and trust"}, {"id": "86984f27-1190-4dba-a622-bc646664f8ff", "type": "concept", "title": "Ethics of corporate and UX research"}], "description": "Students examine how workplace culture shapes adoption, resistance, and technology use."}]}, {"id": "881e8771-d55d-44f9-b6c4-1d17f7cfce13", "type": "topic", "title": "Medical Anthropology, Public Health, and Social Determinants", "description": "This section connects culture, embodiment, inequality, health systems, and community intervention.", "children": [{"id": "b439a412-1449-4575-a8ec-15f73599e31e", "type": "subtopic", "title": "Illness experience and care systems", "children": [{"id": "6e8567a5-6bfd-477d-a56f-72b1a4be2dc9", "type": "concept", "title": "Explanatory models"}, {"id": "fc2a3ebb-397c-4d8a-89be-5c00bd7c313b", "type": "concept", "title": "Therapeutic pluralism"}, {"id": "e7a49b89-d583-4f5b-b090-c3ecd76bb211", "type": "concept", "title": "Clinical communication and trust"}], "description": "Students learn why health behaviors make sense within local worlds of meaning and constraint."}, {"id": "fe428ea8-93a5-49b7-b437-26c9dfdbd581", "type": "subtopic", "title": "Structural violence and social determinants", "children": [{"id": "f9abfe0d-8f39-4d50-98d4-dae3e1725299", "type": "concept", "title": "Structural vulnerability"}, {"id": "38cf0ea7-8c50-4e33-9a0c-a417768c2abc", "type": "concept", "title": "Health inequity"}, {"id": "cdae3546-7fe4-4158-b452-510fcfff276b", "type": "concept", "title": "Food, housing, work, and environmental exposures"}], "description": "The focus is on how poverty, racism, migration, housing, labor, and policy become embodied."}, {"id": "3674629b-dd76-4529-976d-f6c11edc7f49", "type": "subtopic", "title": "Community health intervention", "children": [{"id": "68238c91-f7da-43f8-86e5-a58a58b8988e", "type": "concept", "title": "Community-based participatory research"}, {"id": "130569be-0b27-4c8d-bca2-7cf33beece67", "type": "concept", "title": "Behavioral interventions in context"}, {"id": "6a15c014-89e0-4ee8-9f2d-9c3e712b9d40", "type": "concept", "title": "Dissemination and sustainability"}], "description": "Students learn how anthropology supports culturally responsive public health work."}]}, {"id": "7de02857-e7e7-404a-ba43-655e18f6ba2a", "type": "topic", "title": "Environmental, Climate, and Disaster Anthropology", "description": "Applied anthropology can explain how communities experience environmental change and how policy responses succeed or fail locally.", "children": [{"id": "940218a7-5892-4ad6-b8cb-8ba5ff58ac32", "type": "subtopic", "title": "Human-environment relations", "children": [{"id": "ec936679-e10f-4643-9b21-ab92b4dd0116", "type": "concept", "title": "Political ecology"}, {"id": "5c80b8df-fbb2-40d9-a416-816d08a1157b", "type": "concept", "title": "Traditional and local ecological knowledge"}, {"id": "460e9b09-9d71-4212-9308-836d5deab2a2", "type": "concept", "title": "Resource access and conflict"}], "description": "Students learn to examine environment as lived place, livelihood, identity, and political terrain."}, {"id": "862df696-e78f-4a8c-b099-a0436cc994d3", "type": "subtopic", "title": "Climate adaptation and resilience", "children": [{"id": "e05c38df-b6b0-4139-bf09-d5218256d627", "type": "concept", "title": "Risk perception"}, {"id": "5cea7ec8-f501-4ed0-b09a-8d794bb6193a", "type": "concept", "title": "Relocation and managed retreat"}, {"id": "6742c687-9c30-4f6e-a74d-641ca706da1c", "type": "concept", "title": "Equity in resilience planning"}], "description": "The gist is to link adaptation planning with culture, inequality, and community capacity."}, {"id": "02f71eae-3f2a-40af-b32d-f2e9347d1675", "type": "subtopic", "title": "Disaster response and recovery", "children": [{"id": "89bf41f1-5a64-4a58-b5ec-c1002c48890e", "type": "concept", "title": "Preparedness and mutual aid"}, {"id": "1537c133-5c7e-48d6-ba19-748840028677", "type": "concept", "title": "Humanitarian logistics and local knowledge"}, {"id": "7ecdfc1e-6901-4980-97d0-d13e2652ea02", "type": "concept", "title": "Recovery, trauma, and displacement"}], "description": "Students study why social networks, trust, and institutions shape disaster outcomes."}]}, {"id": "ce833aeb-9791-4668-9dff-2eaefddfb002", "type": "topic", "title": "Development, Humanitarianism, and Global Governance", "description": "This section examines international development and humanitarian action through culture, power, institutions, and unintended consequences.", "children": [{"id": "1077964a-4e03-405e-887a-d2cd9f88e751", "type": "subtopic", "title": "Development as cultural and political practice", "children": [{"id": "3f3ea881-923a-4908-baab-63d7d241083d", "type": "concept", "title": "Modernization and post-development critiques"}, {"id": "7b8cd97f-976c-479a-ab50-0785877544df", "type": "concept", "title": "NGOs, donors, and state actors"}, {"id": "55368156-1891-4ed3-a0b8-6d7947847579", "type": "concept", "title": "Participation and local ownership"}], "description": "Students learn that development projects carry assumptions about progress, expertise, and value."}, {"id": "7ed19a7c-1062-4541-a840-09738a48e8df", "type": "subtopic", "title": "Humanitarian settings", "children": [{"id": "4ae44b16-daff-415d-9417-74e9d923c59e", "type": "concept", "title": "Refugee and migrant health"}, {"id": "2d59868e-434a-431a-a6fe-074a50d0a349", "type": "concept", "title": "Protection, dignity, and accountability"}, {"id": "b8053dcd-7bba-4980-924f-5e370420b0cd", "type": "concept", "title": "Coordination with local institutions"}], "description": "The point is to understand crisis response as a social field, not only a logistical operation."}, {"id": "e74356f7-d4ac-4edc-bb1a-0f6a1f751794", "type": "subtopic", "title": "Global governance and ethics", "children": [{"id": "705b923a-62e9-45fc-93f3-707349779415", "type": "concept", "title": "WHO, UN, NGOs, and multilateral systems"}, {"id": "ccbcd70b-1e9c-45b6-a355-32e54bf4be97", "type": "concept", "title": "Global health ethics"}, {"id": "effe505c-cacb-4353-938d-13899d0f73e2", "type": "concept", "title": "Sustainable Development Goals and equity"}], "description": "Students connect local experience to international agencies, rules, and funding structures."}]}, {"id": "2e1fe7de-90d7-4950-92d2-8a1af653cd36", "type": "topic", "title": "Economic, Political, and Legal Anthropology in Practice", "description": "Applied anthropologists often work where markets, states, law, and everyday survival intersect.", "children": [{"id": "6f40b777-2541-40f7-88a4-5c73491c6e6c", "type": "subtopic", "title": "Economy and livelihood", "children": [{"id": "139a6c70-fadc-4340-b5df-b51bf7912914", "type": "concept", "title": "Moral economies"}, {"id": "8c833f1a-3fd2-46ca-893d-61c76a280e5d", "type": "concept", "title": "Precarity and labor regimes"}, {"id": "cca676b5-bcce-449a-9784-db81396b2fe5", "type": "concept", "title": "Household finance and survival strategies"}], "description": "Students learn to analyze informal economies, labor, exchange, debt, and household strategies."}, {"id": "d5380563-cb6b-4ffa-a5c7-ce5a8359b9af", "type": "subtopic", "title": "Power, governance, and policy", "children": [{"id": "30b2f234-1c93-4a06-a77a-0970c79f91bd", "type": "concept", "title": "Bureaucracy and frontline discretion"}, {"id": "0b81aee3-6f26-476f-bcc4-a94349c28bcd", "type": "concept", "title": "Policy design and delivery"}, {"id": "673fa49a-3417-437a-a91c-4dc80ebd0800", "type": "concept", "title": "Legitimacy, trust, and accountability"}], "description": "The focus is on how institutions govern people and how people navigate institutions."}, {"id": "46cd5edf-4c86-44dd-993d-fe38f3d58063", "type": "subtopic", "title": "Legal and rights-based applications", "children": [{"id": "15d08404-7679-4971-bb92-6b8273e90887", "type": "concept", "title": "Human rights documentation"}, {"id": "d5d56d7e-34f4-4976-bff1-e744f362dc4d", "type": "concept", "title": "Expert testimony and cultural evidence"}, {"id": "663ec548-156f-4a6a-8982-2e654ae6bd9b", "type": "concept", "title": "Legal pluralism and access to justice"}], "description": "Students examine how anthropology contributes to rights claims, law, conflict, and justice."}]}, {"id": "79484748-1469-4efd-bc98-b6d67045a68e", "type": "topic", "title": "Cultural Resource Management and Heritage Practice", "description": "This section covers applied work around archaeology, heritage, museums, memory, land, and public stewardship.", "children": [{"id": "a8d4028c-9eda-41c1-9fba-6c1ddb6a46c4", "type": "subtopic", "title": "Cultural resource management", "children": [{"id": "bf6594a9-cd24-451c-9f3f-bff44f87c74b", "type": "concept", "title": "Survey and site documentation"}, {"id": "77a14580-70de-4a93-a77e-923ac8f1668a", "type": "concept", "title": "Compliance and consultation"}, {"id": "55c8b4f9-999a-44dc-9006-ae670fd74828", "type": "concept", "title": "Impact assessment and mitigation"}], "description": "Students learn the professional logic of protecting material heritage within planning and regulatory systems."}, {"id": "24a174f3-ebdb-4cd9-bbae-db06ef66375a", "type": "subtopic", "title": "Museums and public heritage", "children": [{"id": "979dcc77-43be-4502-a600-45948204dd4f", "type": "concept", "title": "Interpretation and representation"}, {"id": "ee81cb7d-4afa-477b-bb8d-1ab737ffc49d", "type": "concept", "title": "Repatriation and NAGPRA context"}, {"id": "1af27e26-ebe0-4050-939e-923e80f7b3b6", "type": "concept", "title": "Community-curated heritage"}], "description": "The point is to understand collections and exhibitions as public anthropology with political stakes."}, {"id": "d6d0b703-f7ab-4dd5-a72e-962f315ca515", "type": "subtopic", "title": "Heritage conflict and stewardship", "children": [{"id": "6dfbc1e2-3cdd-410b-95e9-883915fad651", "type": "concept", "title": "Sacred sites and landscape"}, {"id": "5cf13f3f-5100-4c40-9e54-cf5ac60f08c9", "type": "concept", "title": "Intangible cultural heritage"}, {"id": "272750b0-dc49-45c1-af7b-d359f2089990", "type": "concept", "title": "Tourism, commodification, and preservation"}], "description": "Students learn how heritage claims can involve identity, land, tourism, and repair."}]}, {"id": "42fc4f8b-1ee0-47d3-a987-c1556a3c8b92", "type": "topic", "title": "Organizations, Work, and Business Anthropology", "description": "Anthropological methods are increasingly used to understand work cultures, organizations, markets, and technology adoption.", "children": [{"id": "97b6c11e-4f0e-4aa0-9a66-42f1343d0247", "type": "subtopic", "title": "Organizational culture", "children": [{"id": "2a33ff66-c88a-4899-b9e6-84b400f4d95b", "type": "concept", "title": "Meetings, routines, and artifacts"}, {"id": "27849907-f6c9-4299-bc2a-c6894c13daab", "type": "concept", "title": "Status, hierarchy, and informal authority"}, {"id": "df68ee27-4706-4511-be7a-0302eea1ca76", "type": "concept", "title": "Organizational change and resistance"}], "description": "Students learn to read workplaces as cultural systems with norms, rituals, incentives, and hidden assumptions."}, {"id": "36d6c7db-9d12-428e-b49f-ecd7f9a7fd0b", "type": "subtopic", "title": "Consumer and market anthropology", "children": [{"id": "d585d89d-fe37-4366-bc62-08671e558556", "type": "concept", "title": "Meaning and material culture"}, {"id": "74f55cf7-8d9b-4f28-ad3e-789b1a28acef", "type": "concept", "title": "Household decision-making"}, {"id": "d937e95e-4de9-427b-bec1-a399f080d27a", "type": "concept", "title": "Market research ethics"}], "description": "The gist is that consumption is social, symbolic, practical, and embedded in identity."}, {"id": "72a7e8ca-fb00-4dc2-b58e-9e3db765ed75", "type": "subtopic", "title": "Technology and workplace futures", "children": [{"id": "8e2bcf89-3fd6-4ed7-bc7b-e2d51197de13", "type": "concept", "title": "Adoption and workarounds"}, {"id": "40a213c3-55ba-4dfb-9578-6c480c456fb0", "type": "concept", "title": "Digital inequality"}, {"id": "c0645efc-e810-4563-a353-bf67e640ba57", "type": "concept", "title": "AI, automation, and human judgment"}], "description": "Students examine how people actually use technologies in situated work."}]}, {"id": "424ed1de-02b9-42c1-8778-c5444c4f6137", "type": "topic", "title": "Education, Communication, and Public Anthropology", "description": "Applied anthropologists help institutions understand learning, communication, identity, and cultural mismatch in schools and public programs.", "children": [{"id": "b30ba701-db6e-4960-b156-095988f265a8", "type": "subtopic", "title": "Anthropology of education", "children": [{"id": "28c4280e-c06d-427a-86af-4cc034dcdfe4", "type": "concept", "title": "Hidden curriculum"}, {"id": "402b1ae4-5eec-44ce-b0eb-b45e2496ee5e", "type": "concept", "title": "Family-school relationships"}, {"id": "8b96ff7f-1eea-43ea-8d41-29a31cb7f299", "type": "concept", "title": "Culturally sustaining pedagogy"}], "description": "Students learn how schooling reflects and reproduces culture, inequality, language, and power."}, {"id": "97acb39a-0ad8-46e5-aaef-c40e9d5cbeb3", "type": "subtopic", "title": "Intercultural communication", "children": [{"id": "7a84da16-efca-4522-8a4a-1a7fab8e2689", "type": "concept", "title": "Language ideology"}, {"id": "6b0cb775-147b-4aac-bfa0-46b66c0d57e8", "type": "concept", "title": "Translation and mediation"}, {"id": "2348854d-e5ae-4f7b-b896-dd23f142a2a8", "type": "concept", "title": "Miscommunication in institutions"}], "description": "The point is to move beyond stereotypes toward careful analysis of language, meaning, and interaction."}, {"id": "948f16f9-c2f8-4883-bc7d-0b8fa8a159ba", "type": "subtopic", "title": "Public education and outreach", "children": [{"id": "7c9237bc-1d33-465b-ae59-274f59442d3f", "type": "concept", "title": "Plain-language communication"}, {"id": "627df9dd-f8bd-45bf-8c1b-4704f66d830a", "type": "concept", "title": "Workshops and training"}, {"id": "785e5d2f-7ae9-402b-b0a2-0295b9822233", "type": "concept", "title": "Evaluation of outreach impact"}], "description": "Students practice translating research into materials that nonacademic audiences can use."}]}, {"id": "a70d0743-90c4-4f01-9bfe-fbe4b97fb413", "type": "topic", "title": "Policy Translation, Advocacy, and Public Communication", "description": "This section teaches students to turn anthropological evidence into briefs, recommendations, testimony, and public-facing arguments.", "children": [{"id": "fb730f3a-2feb-4042-8c25-264957b89c9d", "type": "subtopic", "title": "Policy analysis for anthropologists", "children": [{"id": "65114729-b9ad-4221-b665-1c8b25ebf49e", "type": "concept", "title": "Problem framing"}, {"id": "71ca9775-563c-4489-9490-f3faf4b21618", "type": "concept", "title": "Policy alternatives and tradeoffs"}, {"id": "3c4f61de-5525-492f-ba9f-f4d7ffda6454", "type": "concept", "title": "Equity and feasibility analysis"}], "description": "Students learn how evidence becomes useful when matched to institutions, options, and constraints."}, {"id": "aa6e8425-32c9-4579-be42-5969fca04264", "type": "subtopic", "title": "Advocacy and coalition communication", "children": [{"id": "329aa4b0-9eda-442a-ad17-8bb73e1850c7", "type": "concept", "title": "Framing and audience analysis"}, {"id": "e62b29d6-af96-46b5-8cdd-7d7eea5ae136", "type": "concept", "title": "Coalition messaging"}, {"id": "9226b6ef-d59e-4fd9-85d2-b9215f160f11", "type": "concept", "title": "Ethical advocacy boundaries"}], "description": "The gist is to communicate without losing complexity or community accountability."}, {"id": "4f086ee8-3d74-4251-b7be-593a28f82d77", "type": "subtopic", "title": "Applied deliverables", "children": [{"id": "26fa7204-91dc-475f-a093-3cd0e185bacf", "type": "concept", "title": "Executive summaries"}, {"id": "e979dd5d-8424-4052-ab76-ea39baeb228f", "type": "concept", "title": "Policy memos and client briefs"}, {"id": "86b1418d-fe0a-462a-a8a9-03c7f3760153", "type": "concept", "title": "Visual storytelling and presentations"}], "description": "Students practice formats used in professional settings."}]}, {"id": "9b2b6801-edf2-4c6d-b90d-e9e88e7e361e", "type": "topic", "title": "Community Organizing, Participatory Action, and Coalition Building", "description": "Applied anthropology can support community change by mapping power, building capacity, and sustaining collective action.", "children": [{"id": "5a834ffa-ff65-418e-ad8f-4176c309580d", "type": "subtopic", "title": "Community practice models", "children": [{"id": "364c5fec-464b-44f7-aca0-beca3328b4e9", "type": "concept", "title": "Community organizing"}, {"id": "1215dd69-d4d6-4dbb-91cd-170acd6e8a36", "type": "concept", "title": "Asset-based development"}, {"id": "be6af738-36f4-4b54-a644-0acbe52a9154", "type": "concept", "title": "Popular education and mutual aid"}], "description": "Students compare organizing, development, planning, and empowerment traditions."}, {"id": "7b09a5ca-7d90-4f70-86eb-e6fd5e435fb3", "type": "subtopic", "title": "Power analysis and mobilization", "children": [{"id": "bd0f7a7c-bdf9-44ff-a256-f355a305464d", "type": "concept", "title": "Power mapping"}, {"id": "9d721fee-fe14-42b1-ac9b-e9b4252151f1", "type": "concept", "title": "Leadership development"}, {"id": "c080648a-0018-41ad-9fef-0c7801a84617", "type": "concept", "title": "Campaign strategy and tactics"}], "description": "The point is to understand how change happens through relationships, institutions, and pressure."}, {"id": "525bddd9-e631-4a35-99f8-aa98dc012871", "type": "subtopic", "title": "Sustaining change", "children": [{"id": "626d1484-ff66-49bf-b444-b893b6ac7c18", "type": "concept", "title": "Capacity building"}, {"id": "7a64a9e4-5100-49ff-80b5-c0ce8f65a540", "type": "concept", "title": "Institutionalization and scaling"}, {"id": "e908f683-a76c-4d43-b954-585df2acfbdd", "type": "concept", "title": "Feedback loops and adaptive learning"}], "description": "Students learn to think beyond one project cycle."}]}, {"id": "ea7db54f-4bb0-441f-9d83-7493bf8c6e9d", "type": "topic", "title": "Data, Mixed Methods, and Evidence Communication", "description": "World-class applied anthropology requires qualitative depth plus enough quantitative and visual literacy to work across evidence cultures.", "children": [{"id": "b91871de-75eb-429f-b83e-46df209424c8", "type": "subtopic", "title": "Mixed-method design", "children": [{"id": "784ed4a2-b7c0-462a-b885-6708a9cb363b", "type": "concept", "title": "Sequential and convergent designs"}, {"id": "1a219c88-a6b6-40cf-84c9-0c7d27f548a0", "type": "concept", "title": "Sampling logic across methods"}, {"id": "5a68ad6b-194e-41b6-8256-2ce5eb3f82e5", "type": "concept", "title": "Triangulation and complementarity"}], "description": "Students learn when to combine ethnography with surveys, administrative data, GIS, or experiments."}, {"id": "49835984-b01f-40fe-b5ef-f6e075856aef", "type": "subtopic", "title": "Analysis and synthesis", "children": [{"id": "254225d2-c1bb-4a13-8398-387d5b50048e", "type": "concept", "title": "Coding and memoing"}, {"id": "b213d92a-47fd-4841-9108-4e3d2ace03a0", "type": "concept", "title": "Thematic and framework analysis"}, {"id": "3b71a9c4-d74e-458e-ad79-a8a3e0e8b4e3", "type": "concept", "title": "Evidence matrices and pattern finding"}], "description": "The focus is turning messy data into credible findings."}, {"id": "ad456313-f849-49c7-9380-ae03bea27385", "type": "subtopic", "title": "Communicating uncertainty", "children": [{"id": "58b79437-cb7d-446a-aee0-704ce361d3d8", "type": "concept", "title": "Limitations and validity"}, {"id": "0af76aa9-231f-49a0-a006-7f7c3af01661", "type": "concept", "title": "Confidence without overclaiming"}, {"id": "dca90d44-816c-4a9f-aa37-b8427d9aff61", "type": "concept", "title": "Charts, quotes, cases, and recommendations"}], "description": "Students learn to report findings honestly while still being useful."}]}, {"id": "ae7980e2-b037-44a2-b631-8640aff6288a", "type": "topic", "title": "Applied Project / Client Brief Capstone", "description": "The capstone asks students to integrate ethics, methods, analysis, and communication in a practical project for a real or simulated partner.", "children": [{"id": "9dc04fde-315a-4b30-bff0-620690526a6e", "type": "subtopic", "title": "Project scoping", "children": [{"id": "0976e72a-2883-4c71-ad63-3bfe00a5c24c", "type": "concept", "title": "Scope of work"}, {"id": "70057c05-c256-4cd3-968f-b134785b6419", "type": "concept", "title": "Research plan and timeline"}, {"id": "ce2ec5b1-30a2-4464-a0b8-2a52b02684c1", "type": "concept", "title": "Deliverable agreement"}], "description": "Students define a feasible applied problem and negotiate expectations with a client or community partner."}, {"id": "42f26768-83d9-4c37-8017-cd947240be55", "type": "subtopic", "title": "Fieldwork and analysis sprint", "children": [{"id": "2a45abce-c864-4a0b-8728-61d8c92a684d", "type": "concept", "title": "Data collection protocol"}, {"id": "ae771026-be23-4f80-b502-5b45cb29f3c9", "type": "concept", "title": "Team roles and quality control"}, {"id": "54906785-1e26-4f0a-90a9-0577cef8e932", "type": "concept", "title": "Rapid synthesis and member checking"}], "description": "The point is to conduct disciplined, ethical, useful inquiry within realistic constraints."}, {"id": "f9cc055b-efd2-4b22-ab60-78476c76467b", "type": "subtopic", "title": "Final brief and presentation", "children": [{"id": "ce4a13ba-9fbf-4b4b-8eeb-551aeeb10e31", "type": "concept", "title": "Client brief"}, {"id": "117fde18-7d2e-4ab4-a527-5cb99f753fa6", "type": "concept", "title": "Implementation recommendations"}, {"id": "77491077-df0a-4ca6-8c19-cf28e7200f01", "type": "concept", "title": "Reflection on ethics, limitations, and next steps"}], "description": "Students produce a professional deliverable that can guide action."}]}], "dbBacked": true}$apanjson$::jsonb,
